DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.network_acceptance_candidates(uuid,integer,uuid)'::regprocedure) INTO f;f:=replace(f,'IF NOT public.network_source_access(_distribution,true)','IF NOT public.network_source_access(_distribution,false)');EXECUTE f;
SELECT pg_get_functiondef('public.pilot_preview_wave(uuid)'::regprocedure) INTO f;f:=replace(f,'IF NOT public.network_source_access(_distribution,true)','IF NOT public.network_source_access(_distribution,false)');f:=replace(f,'''enabled'',public.pilot_scope_reason(d.id,NULL)=''''','''enabled'',public.network_source_access(d.id,true) AND public.pilot_scope_reason(d.id,NULL)=''''');f:=replace(f,'CASE WHEN public.has_role(auth.uid(),''admin'') THEN','CASE WHEN public.admin_can(''requests'',''read'') AND public.admin_can_account(d.source_workspace_id) THEN');EXECUTE f;
SELECT pg_get_functiondef('public.pilot_activation_checklist(jsonb)'::regprocedure) INTO f;f:=replace(f,'''managed_email'',''driver_schedule_email'',''sms'',''nearby_auto_waves'',''nearby_matching''','''managed_email'',''driver_schedule_email'',''communication_email_delivery'',''patient_reminder_delivery'',''family_notification_delivery'',''digital_guide_delivery'',''sms'',''nearby_auto_waves'',''nearby_matching''');EXECUTE f;END $change$;
CREATE FUNCTION public.invalidate_pilot_geography() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.pickup_area,NEW.pickup_lat,NEW.pickup_lng,NEW.request_id,NEW.trip_id) IS DISTINCT FROM (OLD.pickup_area,OLD.pickup_lat,OLD.pickup_lng,OLD.request_id,OLD.trip_id) THEN NEW.pickup_geography_evidence:='{}'::jsonb;END IF;RETURN NEW;END $$;
CREATE TRIGGER invalidate_pilot_geography BEFORE UPDATE ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.invalidate_pilot_geography();REVOKE ALL ON FUNCTION public.invalidate_pilot_geography() FROM PUBLIC,anon,authenticated;